async function readCryptoArchive(pairId: typeof CRYPTO_ARCHIVE_PAIRS[number], limit: number) {
  const archiveKey = `hevora:candlearchive:${pairId}:5m`;
  const raw = await safeRedisCall(() => redisClient!.lrange<Candle>(archiveKey, -limit, -1), `read_${pairId.toLowerCase()}_archive`);
  const candles = (raw || []).map((c) => ({ t: c.time, o: c.open, h: c.high, l: c.low, c: c.close }));
  return {
    pairId,
    candles,
    count: candles.length,
    source: `${archiveKey} (unbounded, real closed 5m bars only, accumulating since this feature was deployed)`,
    oldestArchivedTime: candles.length > 0 ? new Date(candles[0].t).toISOString() : null,
    newestArchivedTime: candles.length > 0 ? new Date(candles[candles.length - 1].t).toISOString() : null,
    fetchedAt: new Date().toISOString(),
  };
}

