// --- 1e. Daily/Weekly/Monthly (Bagian J Tugas 1, 2026-09-02) ----------------------------------
//
// Separate pipeline from the intraday tick-built one above by design (per the user's own explicit
// instruction not to mix the logic) - fetched on-demand (a reader picks D/W/M in the chart), not
// polled continuously, since EOD bars barely change intraday. Sources, each verified for real via
// scripts/probe-eod-history-sources.ts run on GitHub Actions (this sandbox's own egress to every
// one of these domains is blocked) - never assumed, never fabricated if a source turns out not to
// work:
//   - Crypto (BTC/ETH/SOL): KuCoin (primary) -> OKX (fallback) - both already-integrated exchange
//     fallbacks elsewhere in this file, both confirmed to genuinely support daily/weekly/monthly
//     kline directly, real free data, no new provider.
//   - Forex (EUR/GBP/CHF/CAD): Yahoo Finance, verified individually for all 4 pairs (not assumed
//     from EURUSD alone) - and Yahoo supports native weekly/monthly interval params directly
//     (interval=1wk/1mo), so this never aggregates daily bars itself.
//   - XAU: Yahoo's own spot symbol (XAUUSD=X) is confirmed permanently delisted even at daily
//     granularity - GC=F (COMEX gold futures, front month) is used instead, per the user's own
//     explicit decision. This is a REAL trade-off, not a technicality: futures front-month price
//     tracks spot closely but is NOT identical to it, so a Daily/Weekly/Monthly XAU chart can show
//     a slightly different number than the header/intraday chart (which read spot) - isFuturesProxy
//     and disclosure below exist so the frontend can show a permanent, visible label about this,
//     never silently.
type EodInterval = '1D' | '1W' | '1M';
const EOD_CRYPTO_SYMBOL: Record<'BTCUSDT' | 'ETHUSDT' | 'SOLUSDT', string> = {
  BTCUSDT: 'BTC-USDT', ETHUSDT: 'ETH-USDT', SOLUSDT: 'SOL-USDT',
};
const EOD_FOREX_SYMBOL: Record<'EURUSD' | 'GBPUSD' | 'USDCHF' | 'USDCAD', string> = {
  EURUSD: 'EURUSD=X', GBPUSD: 'GBPUSD=X', USDCHF: 'USDCHF=X', USDCAD: 'USDCAD=X',
};
// EOD bars barely move intraday - cached per (pairId, interval) so repeated chart visits/interval
// switches don't re-hit these providers every time; long enough to be a real cache, short enough
// that a reader who leaves the tab open overnight still sees today's close by morning.
const EOD_CACHE_TTL_MS = 15 * 60 * 1000;
const eodCache: Record<string, { candles: Candle[]; fetchedAt: number }> = {};

async function fetchCryptoEod(symbol: string, interval: EodInterval): Promise<Candle[] | null> {
  const kucoinType = interval === '1D' ? '1day' : interval === '1W' ? '1week' : '1month';
  try {
    const res = await fetch(`https://api.kucoin.com/api/v1/market/candles?type=${kucoinType}&symbol=${symbol}`, { headers: CRYPTO_FETCH_HEADERS });
    if (res.ok) {
      const json = await res.json();
      const list = json?.data;
      // KuCoin candle row: [time(sec), open, close, high, low, volume, turnover] - newest first
      if (Array.isArray(list) && list.length > 0) {
        return list
          .map((k: any) => ({
            time: parseFloat(k[0]) * 1000, open: parseFloat(k[1]), close: parseFloat(k[2]),
            high: parseFloat(k[3]), low: parseFloat(k[4]), volume: parseFloat(k[5]),
          }))
          .reverse();
      }
    }
  } catch {
    // fall through to OKX
  }
  try {
    const okxBar = interval === '1D' ? '1D' : interval === '1W' ? '1W' : '1M';
    const res = await fetch(`https://www.okx.com/api/v5/market/candles?instId=${symbol}&bar=${okxBar}&limit=300`, { headers: CRYPTO_FETCH_HEADERS });
    if (res.ok) {
      const json = await res.json();
      const list = json?.data;
      // OKX candle row: [ts(ms), open, high, low, close, vol, ...] - newest first
      if (Array.isArray(list) && list.length > 0) {
        return list
          .map((k: any) => ({
            time: parseFloat(k[0]), open: parseFloat(k[1]), high: parseFloat(k[2]),
            low: parseFloat(k[3]), close: parseFloat(k[4]), volume: parseFloat(k[5]),
          }))
          .reverse();
      }
    }
  } catch {
    // both failed
  }
  return null;
}

async function fetchYahooEod(symbol: string, interval: EodInterval): Promise<Candle[] | null> {
  const yInterval = interval === '1D' ? '1d' : interval === '1W' ? '1wk' : '1mo';
  const range = interval === '1M' ? 'max' : '5y';
  try {
    const res = await fetch(`https://query1.finance.yahoo.com/v8/finance/chart/${symbol}?interval=${yInterval}&range=${range}`, {
      headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) HEVORA/1.0' },
    });
    if (!res.ok) return null;
    const json = await res.json();
    const result = json?.chart?.result?.[0];
    if (!result || json?.chart?.error) return null;
    const timestamps: number[] = result.timestamp || [];
    const quote = result.indicators?.quote?.[0];
    if (!quote || timestamps.length === 0) return null;
    const candles: Candle[] = [];
    for (let i = 0; i < timestamps.length; i++) {
      if (quote.open[i] != null && quote.high[i] != null && quote.low[i] != null && quote.close[i] != null) {
        candles.push({
          time: timestamps[i] * 1000, open: quote.open[i], high: quote.high[i],
          low: quote.low[i], close: quote.close[i], volume: quote.volume?.[i] || 0,
        });
      }
    }
    return candles.length > 0 ? candles : null;
  } catch {
    return null;
  }
}

app.get('/api/market/eod', async (req, res) => {
  try {
    const pairId = String(req.query.pairId || '').toUpperCase();
    const interval = String(req.query.interval || '1D').toUpperCase();
    if (!['1D', '1W', '1M'].includes(interval)) {
      res.status(400).json({ success: false, error: 'interval must be one of: 1D, 1W, 1M' });
      return;
    }

    const cacheKey = `${pairId}:${interval}`;
    const cached = eodCache[cacheKey];
    const isFresh = cached && Date.now() - cached.fetchedAt < EOD_CACHE_TTL_MS;

    let candles: Candle[] | null = isFresh ? cached!.candles : null;
    let source = '';
    let isFuturesProxy = false;
    let disclosure: string | null = null;

    if (!candles) {
      if (pairId === 'BTCUSDT' || pairId === 'ETHUSDT' || pairId === 'SOLUSDT') {
        candles = await fetchCryptoEod(EOD_CRYPTO_SYMBOL[pairId], interval as EodInterval);
        source = 'KuCoin/OKX (real exchange candles)';
      } else if (pairId === 'XAUUSD') {
        candles = await fetchYahooEod('GC=F', interval as EodInterval);
        source = 'Yahoo Finance GC=F (COMEX gold futures, front month)';
        isFuturesProxy = true;
        disclosure = 'Data futures GC=F - bisa sedikit beda dari harga spot';
      } else if (pairId === 'EURUSD' || pairId === 'GBPUSD' || pairId === 'USDCHF' || pairId === 'USDCAD') {
        candles = await fetchYahooEod(EOD_FOREX_SYMBOL[pairId], interval as EodInterval);
        source = 'Yahoo Finance (spot)';
      } else {
        res.status(400).json({ success: false, error: `No EOD source configured for pairId ${pairId}` });
        return;
      }

      if (!candles) {
        // Honest failure, never fabricated/estimated data - matches this project's standing rule.
        res.status(502).json({ success: false, error: `EOD source unavailable for ${pairId} ${interval} right now - try again shortly.`, pairId, interval });
        return;
      }
      eodCache[cacheKey] = { candles, fetchedAt: Date.now() };
    }

    res.json({
      pairId,
      interval,
      candles: candles.map((c) => ({ t: c.time, o: c.open, h: c.high, l: c.low, c: c.close })),
      count: candles.length,
      source,
      isFuturesProxy,
      disclosure,
      cached: isFresh,
      fetchedAt: new Date().toISOString(),
    });
  } catch (err) {
    console.error('API /api/market/eod error:', err);
    res.status(500).json({ success: false, error: 'Failed to fetch EOD candles' });
  }
});

