// --- 3. Crypto Fear & Greed (alternative.me, free, no key) -----------------------------------
interface FearGreedPoint {
  value: number;
  classification: string | null;
  timestamp: string | null;
}

/** Shared loader, single-flight + 30min-cached via cachedExternalFeed('fear-greed', ...) below -
 * factored out (no behaviour change to the endpoint) so the ask-ai context bundle (Terminal
 * redesign, P1) can read the same cached reading without a second, separately-cached fetch path. */
async function fetchFearGreedPoints(): Promise<FearGreedPoint[]> {
  const upstream = await fetchWithTimeout('https://api.alternative.me/fng/?limit=30', {
    headers: { 'User-Agent': 'HEVORA/1.0' },
  });
  if (!upstream.ok) throw new Error(`HTTP ${upstream.status}`);
  const json: any = await upstream.json();
  const rows = Array.isArray(json?.data) ? json.data : [];
  const points: FearGreedPoint[] = rows
    .map((row: any) => ({
      value: Number(row?.value),
      classification: typeof row?.value_classification === 'string' ? row.value_classification : null,
      timestamp: row?.timestamp ? new Date(Number(row.timestamp) * 1000).toISOString() : null,
    }))
    .filter((point: FearGreedPoint) => Number.isFinite(point.value));
  // A response we cannot parse is a failure, not an empty reading - do not cache a blank as if
  // the provider had legitimately reported nothing.
  if (points.length === 0) throw new Error('No parseable Fear & Greed values in provider response');
  return points;
}

app.get('/api/sentiment/fear-greed', async (_req, res) => {
  const result = await cachedExternalFeed('fear-greed', 30 * 60_000, fetchFearGreedPoints);

  res.json({
    points: result.value ?? [],
    source: 'alternative.me Crypto Fear & Greed Index',
    scope: 'crypto',
    fetchedAt: result.fetchedAt,
    stale: result.stale,
    unavailable: result.value === null,
    error: result.error,
  });
});

// --- 4. CFTC Commitment of Traders (Socrata, free, no key) -----------------------------------
//
// Field names on the public Socrata dataset are resolved defensively through known aliases: if
// the dataset schema shifts, this returns UNAVAILABLE with the reason instead of quietly
// publishing zeros or misreading a column. Reported positions are non-commercial (speculative)
// long/short, which is the series traders read as "institutional positioning".
// `cotClass` groups every tracked market into the six buckets the COT Heat Scan redesign filters
// by (ALL/METALS/FX/ENERGY/AGRI/INDEX/CRYPTO, 2026-09-02) - purely a display grouping, no effect
// on the code/label pairing above it. It also decides which CFTC report a market's category
// breakdown comes from (see COT_FINANCIAL_CLASSES below): TFF only covers financial futures
// (FX/INDEX/CRYPTO), physical commodities (METALS/ENERGY/AGRI) use the Disaggregated report
// instead - two report types with two different category systems, not one.
type CotClass = 'METALS' | 'FX' | 'ENERGY' | 'AGRI' | 'INDEX' | 'CRYPTO';

const COT_MARKET_CODES: Record<string, { code: string; label: string; cotClass: CotClass }> = {
  XAUUSD: { code: '088691', label: 'GOLD - COMMODITY EXCHANGE INC.', cotClass: 'METALS' },
  EURUSD: { code: '099741', label: 'EURO FX - CHICAGO MERCANTILE EXCHANGE', cotClass: 'FX' },
  GBPUSD: { code: '096742', label: 'BRITISH POUND - CHICAGO MERCANTILE EXCHANGE', cotClass: 'FX' },
  USDCHF: { code: '092741', label: 'SWISS FRANC - CHICAGO MERCANTILE EXCHANGE', cotClass: 'FX' },
  USDCAD: { code: '090741', label: 'CANADIAN DOLLAR - CHICAGO MERCANTILE EXCHANGE', cotClass: 'FX' },
  BTCUSDT: { code: '133741', label: 'BITCOIN - CHICAGO MERCANTILE EXCHANGE', cotClass: 'CRYPTO' },
  // Commodity contracts, keyed by the Yahoo futures symbol the Commodities board already uses so
  // one lookup serves both the quote and its positioning. Every label below is the market name the
  // CFTC dataset ACTUALLY returned for that code when scripts/verify-sources.ts probed it - not the
  // name the contract is commonly called. Six of them differed from the obvious guess (067651 is
  // published as WTI-PHYSICAL, and the ICE softs still carry their pre-merger exchange names), and
  // the probe stays critical because a wrong code would not fail loudly: it would quietly attach
  // one market's positioning to another market's name.
  'CL=F': { code: '067651', label: 'WTI-PHYSICAL - NEW YORK MERCANTILE EXCHANGE', cotClass: 'ENERGY' },
  'NG=F': { code: '023651', label: 'NATURAL GAS - NEW YORK MERCANTILE EXCHANGE', cotClass: 'ENERGY' },
  'SI=F': { code: '084691', label: 'SILVER - COMMODITY EXCHANGE INC.', cotClass: 'METALS' },
  'HG=F': { code: '085692', label: 'COPPER-GRADE #1 - COMMODITY EXCHANGE INC.', cotClass: 'METALS' },
  'PL=F': { code: '076651', label: 'PLATINUM - NEW YORK MERCANTILE EXCHANGE', cotClass: 'METALS' },
  'PA=F': { code: '075651', label: 'PALLADIUM - NEW YORK MERCANTILE EXCHANGE', cotClass: 'METALS' },
  'ZW=F': { code: '001602', label: 'WHEAT-SRW - CHICAGO BOARD OF TRADE', cotClass: 'AGRI' },
  'ZC=F': { code: '002602', label: 'CORN - CHICAGO BOARD OF TRADE', cotClass: 'AGRI' },
  'ZS=F': { code: '005602', label: 'SOYBEANS - CHICAGO BOARD OF TRADE', cotClass: 'AGRI' },
  'KC=F': { code: '083731', label: 'COFFEE C - NEW YORK BOARD OF TRADE', cotClass: 'AGRI' },
  'SB=F': { code: '080732', label: 'SUGAR NO. 11 - NEW YORK BOARD OF TRADE', cotClass: 'AGRI' },
  'CC=F': { code: '073732', label: 'COCOA - NEW YORK BOARD OF TRADE', cotClass: 'AGRI' },
  'CT=F': { code: '033661', label: 'COTTON NO. 2 - NEW YORK COTTON EXCHANGE', cotClass: 'AGRI' },
  // USD Index + major US equity index futures (Analysis tab upgrade, 2026-08-26). Keyed by the
  // same Yahoo symbol '/api/indices' (INDEX_SYMBOLS) already quotes them under, same "one lookup
  // serves both" reasoning as the commodities above. Codes were NOT guessed - none of the obvious
  // names matched on the first pass (a plain "%DOLLAR INDEX%"/"%DOW JONES%" search returned zero
  // USD Index rows and only DJIA's REAL ESTATE sub-index), so a live discovery probe was run
  // against the CFTC dataset itself (scripts/verify-sources.ts, GitHub Actions run #32,
  // 2026-08-26) before any of these were wired - every label below is the market name the CFTC
  // dataset ACTUALLY returned for that code, not the name the contract is commonly called.
  'DX-Y.NYB': { code: '098662', label: 'USD INDEX - ICE FUTURES U.S.', cotClass: 'FX' },
  '^GSPC': { code: '13874A', label: 'E-MINI S&P 500 - CHICAGO MERCANTILE EXCHANGE', cotClass: 'INDEX' },
  '^DJI': { code: '124603', label: 'DJIA x $5 - CHICAGO BOARD OF TRADE', cotClass: 'INDEX' },
  // No live quote is wired for the Nasdaq-100 index itself ('/api/indices' only carries the
  // Nasdaq COMPOSITE under ^IXIC) - keyed as '^NDX' (Nasdaq-100's real ticker) rather than
  // reusing ^IXIC, which would misrepresent a Composite quote as sharing positioning data with a
  // Nasdaq-100 contract. Same treatment cotShortLabel already gives BTCUSDT for the same reason.
  '^NDX': { code: '209742', label: 'NASDAQ MINI - CHICAGO MERCANTILE EXCHANGE', cotClass: 'INDEX' },
};

// Financial-futures classes get their category breakdown from CFTC's "Traders in Financial
// Futures" (TFF) report; physical-commodity classes (METALS/ENERGY/AGRI) get theirs from the
// separately-named "Disaggregated" report instead - two real CFTC report types, two different
// category systems (Dealer/Asset Manager/Leveraged Funds/Other Reportables vs Producer-Merchant/
// Swap Dealers/Managed Money/Other Reportables). Never merged into one fake universal label set.
const COT_FINANCIAL_CLASSES: ReadonlySet<CotClass> = new Set(['FX', 'INDEX', 'CRYPTO']);

// CFTC Socrata resource ids - discovered and verified live via
// scripts/verify-cot-breakdown-sources.ts (GitHub Actions runs, 2026-09-02), not guessed:
//   - TFF - Futures Only: the catalog returned TWO resources under this exact name (98ig-3k9y and
//     gpe5-46if). 98ig-3k9y 403'd ("no row or column access to non-tabular tables") when queried;
//     gpe5-46if is the one that actually returns rows (confirmed live for EUR FX and Bitcoin).
//   - Disaggregated - Futures Only: 72hh-3qpy (confirmed live for Gold).
const COT_TFF_RESOURCE_ID = 'gpe5-46if';
const COT_DISAGGREGATED_RESOURCE_ID = '72hh-3qpy';

const pickNumericField = (row: any, aliases: string[]): number | null => {
  for (const alias of aliases) {
    const raw = row?.[alias];
    if (raw !== undefined && raw !== null && raw !== '') {
      const value = Number(raw);
      if (Number.isFinite(value)) return value;
    }
  }
  return null;
};

/** One trader-category row inside a breakdown - `long`/`short` are that category's own reported
 *  contracts (never derived/estimated), `net` is long-short for convenience. */
interface CotCategoryRow {
  key: string;
  label: string;
  long: number;
  short: number;
  net: number;
}

interface CotBreakdown {
  /** Which CFTC report this breakdown's categories came from - the two use different category
   *  systems (see COT_FINANCIAL_CLASSES above), so the client must not assume one fixed label set. */
  system: 'tff' | 'disaggregated';
  categories: CotCategoryRow[];
}

interface CotPositionEntry {
  symbol: string;
  market: string;
  cotClass: CotClass;
  longContracts: number;
  shortContracts: number;
  netContracts: number;
  /** Commercial long/short from the same Legacy dataset row - null only if that dataset's own
   *  columns were ever missing (never fabricated as 0). */
  commercialLong: number | null;
  commercialShort: number | null;
  openInterest: number | null;
  reportDate: string | null;
  percentile: number | null;
  observations: number;
  history: Array<{ date: string | null; net: number }>;
  /** Net-position change vs the immediately preceding weekly report - null with fewer than 2
   *  observations. */
  weeklyChange: number | null;
  /** Null when the TFF/Disaggregated fetch failed or the market wasn't in the cached response -
   *  the client must render "unavailable", never a fabricated breakdown. */
  breakdown: CotBreakdown | null;
}

const cotWeekly = (
  rows: any[],
  code: string
): Array<{ date: string | null; net: number }> =>
  rows
    .filter((candidate) => String(candidate?.cftc_contract_market_code) === code)
    .map((candidate) => {
      const l = pickNumericField(candidate, ['noncomm_positions_long_all', 'noncomm_positions_long_all_1']);
      const sh = pickNumericField(candidate, ['noncomm_positions_short_all', 'noncomm_positions_short_all_1']);
      const date = candidate?.report_date_as_yyyy_mm_dd || null;
      return l === null || sh === null ? null : { date: date ? String(date) : null, net: l - sh };
    })
    .filter(Boolean) as Array<{ date: string | null; net: number }>;

/** Fetches one market's most recent row from a CFTC breakdown dataset (TFF or Disaggregated) and
 *  reads out the given fields - shared by both breakdown fetches below since they only differ in
 *  resource id and which fields they read. Returns null (never a fabricated zero row) on any
 *  failure: HTTP error, no row for that code, or a missing field. */
async function fetchCotBreakdownRow(
  resourceId: string,
  code: string,
  fields: Array<{ key: string; label: string; longField: string; shortField: string }>
): Promise<CotCategoryRow[] | null> {
  try {
    const url =
      `https://publicreporting.cftc.gov/resource/${resourceId}.json` +
      `?$where=cftc_contract_market_code='${code}'` +
      '&$order=report_date_as_yyyy_mm_dd DESC&$limit=1';
    const upstream = await fetchWithTimeout(url, { headers: { 'User-Agent': 'HEVORA/1.0', Accept: 'application/json' } });
    if (!upstream.ok) return null;
    const rows: any[] = await upstream.json();
    const row = Array.isArray(rows) ? rows[0] : null;
    if (!row) return null;

    const categories: CotCategoryRow[] = [];
    for (const f of fields) {
      const long = pickNumericField(row, [f.longField]);
      const short = pickNumericField(row, [f.shortField]);
      if (long === null || short === null) continue;
      categories.push({ key: f.key, label: f.label, long, short, net: long - short });
    }
    return categories.length > 0 ? categories : null;
  } catch {
    return null;
  }
}

// Real CFTC category field names, verified live (not guessed) via
// scripts/verify-cot-breakdown-sources.ts - see COT_TFF_RESOURCE_ID/COT_DISAGGREGATED_RESOURCE_ID
// above for the resources these were read from.
const COT_TFF_FIELDS = [
  { key: 'dealer', label: 'Dealer', longField: 'dealer_positions_long_all', shortField: 'dealer_positions_short_all' },
  { key: 'assetManager', label: 'Asset Manager', longField: 'asset_mgr_positions_long', shortField: 'asset_mgr_positions_short' },
  { key: 'leveragedFunds', label: 'Leveraged Funds', longField: 'lev_money_positions_long', shortField: 'lev_money_positions_short' },
  { key: 'otherReportables', label: 'Other Reportables', longField: 'other_rept_positions_long', shortField: 'other_rept_positions_short' },
];
const COT_DISAGGREGATED_FIELDS = [
  { key: 'producerMerchant', label: 'Producer/Merchant', longField: 'prod_merc_positions_long', shortField: 'prod_merc_positions_short' },
  // Real CFTC field name asymmetry, not a typo: the short/spread swap-dealer columns on this
  // dataset carry a double underscore ("swap__positions_...") that the long column does not.
  { key: 'swapDealers', label: 'Swap Dealers', longField: 'swap_positions_long_all', shortField: 'swap__positions_short_all' },
  { key: 'managedMoney', label: 'Managed Money', longField: 'm_money_positions_long_all', shortField: 'm_money_positions_short_all' },
  { key: 'otherReportables', label: 'Other Reportables', longField: 'other_rept_positions_long', shortField: 'other_rept_positions_short' },
];

/** Shared loader, single-flight + 6h-cached via cachedExternalFeed('cot', ...) below - factored
 * out (no behaviour change to the endpoint) so the ask-ai context bundle (Terminal redesign, P1)
 * can read the same cached snapshot without a second, separately-cached fetch path. */
async function fetchCotPositions(): Promise<Record<string, CotPositionEntry>> {
  const codes = Object.values(COT_MARKET_CODES).map((entry) => `'${entry.code}'`).join(',');
  const url =
    'https://publicreporting.cftc.gov/resource/6dca-aqww.json' +
    `?$where=cftc_contract_market_code in(${codes})` +
    // One row per market per week: with ~19 markets, 200 rows was barely ten weeks each and the
    // percentile stayed null. 1000 is Socrata's page size and gives each market ~50 observations.
    '&$order=report_date_as_yyyy_mm_dd DESC&$limit=1000';

  const upstream = await fetchWithTimeout(url, { headers: { 'User-Agent': 'HEVORA/1.0', Accept: 'application/json' } });
  if (!upstream.ok) throw new Error(`HTTP ${upstream.status}`);
  const rows: any[] = await upstream.json();
  if (!Array.isArray(rows) || rows.length === 0) throw new Error('COT dataset returned no rows');

  const bySymbol: Record<string, CotPositionEntry> = {};
  for (const [symbol, meta] of Object.entries(COT_MARKET_CODES)) {
    const row = rows.find((candidate) => String(candidate?.cftc_contract_market_code) === meta.code);
    if (!row) continue;

    const long = pickNumericField(row, ['noncomm_positions_long_all', 'noncomm_positions_long_all_1']);
    const short = pickNumericField(row, ['noncomm_positions_short_all', 'noncomm_positions_short_all_1']);
    if (long === null || short === null) continue;

    const commercialLong = pickNumericField(row, ['comm_positions_long_all']);
    const commercialShort = pickNumericField(row, ['comm_positions_short_all']);
    const openInterest = pickNumericField(row, ['open_interest_all', 'oi_all']);
    const reportDate =
      row?.report_date_as_yyyy_mm_dd || row?.report_date_as_yyyy_mm_dd_1 || row?.yyyy_report_week_ww || null;

    // Net-position history for this contract, so the client can rank the latest reading against
    // its own past instead of showing a raw contract count no one can calibrate. Percentile is
    // computed here (the rows are already in hand) and is null below eight observations - a
    // percentile from three points is noise wearing a statistic's clothes.
    const seriesRows = cotWeekly(rows, meta.code);

    const nets = seriesRows.map((r) => r.net);
    const net = long - short;
    const percentile =
      nets.length >= 8
        ? (nets.filter((value) => value <= net).length / nets.length) * 100
        : null;
    // seriesRows is already ordered most-recent-first (the upstream query's own $order) - index 1
    // is the immediately preceding weekly report, not an arbitrary older one.
    const weeklyChange = seriesRows.length >= 2 ? seriesRows[0].net - seriesRows[1].net : null;

    bySymbol[symbol] = {
      symbol,
      market: meta.label,
      cotClass: meta.cotClass,
      longContracts: long,
      shortContracts: short,
      netContracts: net,
      commercialLong,
      commercialShort,
      openInterest,
      reportDate: reportDate ? String(reportDate) : null,
      percentile,
      observations: nets.length,
      history: seriesRows.slice(0, 60),
      weeklyChange,
      breakdown: null,
    };
  }

  if (Object.keys(bySymbol).length === 0) {
    throw new Error('COT rows present but no expected position columns could be read');
  }

  // Category breakdown: two more requests, one per report type, each covering only the markets
  // that report belongs to (see COT_FINANCIAL_CLASSES) - never merged into one fake label set.
  // Failure here is non-fatal to the whole response: a market keeps its real Non-Commercial/
  // Commercial numbers with breakdown left null (rendered as "unavailable" client-side) rather
  // than losing everything because one of two extra datasets had a bad moment.
  await Promise.all(
    Object.entries(COT_MARKET_CODES).map(async ([symbol, meta]) => {
      const entry = bySymbol[symbol];
      if (!entry) return;
      const isFinancial = COT_FINANCIAL_CLASSES.has(meta.cotClass);
      const categories = await fetchCotBreakdownRow(
        isFinancial ? COT_TFF_RESOURCE_ID : COT_DISAGGREGATED_RESOURCE_ID,
        meta.code,
        isFinancial ? COT_TFF_FIELDS : COT_DISAGGREGATED_FIELDS
      );
      if (categories) {
        entry.breakdown = { system: isFinancial ? 'tff' : 'disaggregated', categories };
      }
    })
  );

  return bySymbol;
}

app.get('/api/positioning/cot', async (_req, res) => {
  const result = await cachedExternalFeed('cot', 6 * 60 * 60_000, fetchCotPositions);

  res.json({
    positions: result.value ?? {},
    source: 'CFTC Commitment of Traders (non-commercial, Socrata public dataset)',
    fetchedAt: result.fetchedAt,
    stale: result.stale,
    unavailable: result.value === null,
    error: result.error,
  });
});

// --- 7. XAU daily close history (already collected, now readable) ----------------------------
//
// The engine has been forward-archiving one gold close per day for a while (recordXauDailyPrice,
// up to 400 days, Redis + file). The Confluence Engine's historical-analog section needs it: it
// answers "when conditions looked like this before, what did gold actually do next" from real
// recorded closes. Publishing it read-only costs nothing and avoids a second, differently-sourced
// price history.
//
// It starts empty on a fresh deployment and only grows forward - never backfilled - so the client
// is told exactly how many days exist and refuses to draw conclusions from too few.
app.get('/api/market/xau-daily', async (_req, res) => {
  if (xauDailyPriceCache === null) {
    xauDailyPriceCache = await loadXauDailyPriceHistory();
  }
  const points = xauDailyPriceCache ?? [];
  res.json({
    points,
    count: points.length,
    firstDate: points[0]?.date ?? null,
    lastDate: points[points.length - 1]?.date ?? null,
    source: 'HEVORA forward-archived daily close (never backfilled)',
  });
});

// --- 7b. Commodities board: futures quotes, daily closes, EIA inventories ---------------------
//
// Every symbol below was probed by scripts/verify-sources.ts before being wired (run #3: Yahoo
// futures 15/15 OK, EIA crude stocks OK). Nothing here is derived or filled in: a symbol whose
// quote cannot be read comes back with null values and its own error string, and the board shows
// it as UNAVAILABLE rather than dropping it silently or carrying yesterday's number forward.

interface CommodityQuote {
  symbol: string;
  name: string;
  group: 'energy' | 'metals' | 'agriculture';
  price: number | null;
  previousClose: number | null;
  change: number | null;
  changePercent: number | null;
  currency: string | null;
  marketState: string | null;
  quoteTime: string | null;
  error?: string;
}

const COMMODITY_SYMBOLS: Array<{ symbol: string; name: string; group: CommodityQuote['group'] }> = [
  { symbol: 'CL=F', name: 'WTI Crude', group: 'energy' },
  { symbol: 'BZ=F', name: 'Brent Crude', group: 'energy' },
  { symbol: 'NG=F', name: 'Natural Gas', group: 'energy' },
  { symbol: 'GC=F', name: 'Gold Futures', group: 'metals' },
  { symbol: 'SI=F', name: 'Silver', group: 'metals' },
  { symbol: 'HG=F', name: 'Copper', group: 'metals' },
  { symbol: 'PL=F', name: 'Platinum', group: 'metals' },
  { symbol: 'PA=F', name: 'Palladium', group: 'metals' },
  { symbol: 'ZW=F', name: 'Wheat', group: 'agriculture' },
  { symbol: 'ZC=F', name: 'Corn', group: 'agriculture' },
  { symbol: 'ZS=F', name: 'Soybeans', group: 'agriculture' },
  { symbol: 'KC=F', name: 'Coffee', group: 'agriculture' },
  { symbol: 'SB=F', name: 'Sugar', group: 'agriculture' },
  { symbol: 'CC=F', name: 'Cocoa', group: 'agriculture' },
  { symbol: 'CT=F', name: 'Cotton', group: 'agriculture' },
];

const YAHOO_UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) HEVORA/1.0';

async function fetchCommodityQuote(entry: (typeof COMMODITY_SYMBOLS)[number]): Promise<CommodityQuote> {
  const base: CommodityQuote = {
    symbol: entry.symbol,
    name: entry.name,
    group: entry.group,
    price: null,
    previousClose: null,
    change: null,
    changePercent: null,
    currency: null,
    marketState: null,
    quoteTime: null,
  };

  try {
    const upstream = await fetch(
      `https://query1.finance.yahoo.com/v8/finance/chart/${encodeURIComponent(entry.symbol)}?interval=1d&range=5d`,
      { headers: { 'User-Agent': YAHOO_UA } }
    );
    if (!upstream.ok) return { ...base, error: `HTTP ${upstream.status}` };

    const json: any = await upstream.json();
    const meta = json?.chart?.result?.[0]?.meta;
    if (!meta || typeof meta.regularMarketPrice !== 'number') {
      return { ...base, error: 'No quote in provider response' };
    }

    const price: number = meta.regularMarketPrice;
    const previousClose: number | null =
      typeof meta.chartPreviousClose === 'number'
        ? meta.chartPreviousClose
        : typeof meta.previousClose === 'number'
          ? meta.previousClose
          : null;

    return {
      ...base,
      price,
      previousClose,
      change: previousClose === null ? null : price - previousClose,
      changePercent:
        previousClose === null || previousClose === 0 ? null : ((price - previousClose) / previousClose) * 100,
      currency: typeof meta.currency === 'string' ? meta.currency : null,
      marketState: typeof meta.marketState === 'string' ? meta.marketState : null,
      quoteTime:
        typeof meta.regularMarketTime === 'number' ? new Date(meta.regularMarketTime * 1000).toISOString() : null,
    };
  } catch (e: any) {
    return { ...base, error: e?.message || 'Network error' };
  }
}

/** Extracted (HEVAI overhaul PR 9) so gatherAskAiExtraContext can share this exact cache entry
 *  ('commodities-board', the same key this route already uses) instead of re-implementing the
 *  loader - a second call within the 60s TTL is just a Map read, no extra Yahoo request. */
async function fetchCommoditiesBoard(): Promise<CommodityQuote[]> {
  const quotes = await Promise.all(COMMODITY_SYMBOLS.map(fetchCommodityQuote));
  if (quotes.every((q) => q.price === null)) {
    // Not one symbol answered: that is a provider outage, not fifteen coincidences. Throwing
    // lets cachedExternalFeed serve the last good snapshot flagged stale, which is honest,
    // instead of publishing a board of nulls as if the market had gone quiet.
    throw new Error(quotes[0]?.error || 'No commodity quotes returned');
  }
  return quotes;
}

app.get('/api/market/commodities', async (_req, res) => {
  const result = await cachedExternalFeed('commodities-board', 60_000, fetchCommoditiesBoard);

  res.json({
    commodities: result.value ?? [],
    source: 'Yahoo Finance (futures)',
    fetchedAt: result.fetchedAt,
    stale: result.stale,
    unavailable: result.value === null,
    error: result.error,
  });
});

// --- XAU Futures Curve (Tahap D §13-15) --------------------------------------------------------
//
// Individual COMEX gold futures contracts - not the GC=F continuous front-month this app already
// uses for spot/seasonality, but each specific delivery month, so the curve's shape (contango vs
// backwardation) is visible instead of collapsed into one number.
//
// Verified via a real GitHub Actions run before this was built (this sandbox has zero network
// access): the bare symbol (e.g. "GCZ26") 404s on Yahoo, the ".CMX" exchange suffix is required,
// and 5 different contract months across two calendar years all resolved with distinct,
// curve-consistent prices (increasing from the near month outward - real contango, not the same
// quote repeated under 5 names). See scripts/verify-sources.ts's 'XAU Futures Curve' group.
//
// Contract months follow COMEX gold's own standard listed cycle (Feb/Apr/Jun/Aug/Oct/Dec, i.e.
// every even month) - this is the exchange's listing convention, not a per-run guess. The
// CURRENT calendar month is deliberately excluded even when it is itself a listed month: only
// the 5 specific month/year combinations actually proven reachable above were verified, and this
// generalizes the month-code + 2-digit-year naming pattern (a standard, well-documented futures
// symbol convention) rather than the specific Aug-2026 case, which was never itself probed.

interface GoldFuturesContractQuote {
  symbol: string;
  label: string;
  month: number;
  year: number;
  price: number | null;
  error?: string;
}

const GOLD_FUTURES_MONTH_CODE: Record<number, string> = { 2: 'G', 4: 'J', 6: 'M', 8: 'Q', 10: 'V', 12: 'Z' };
const MONTH_NAME_SHORT = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

function nextGoldFuturesContracts(
  count: number,
  from: Date = new Date()
): Array<{ symbol: string; label: string; month: number; year: number }> {
  const contracts: Array<{ symbol: string; label: string; month: number; year: number }> = [];
  let year = from.getUTCFullYear();
  let month = from.getUTCMonth() + 2; // 1-12 current month, then step past it (see comment above)
  while (contracts.length < count) {
    if (month > 12) {
      month -= 12;
      year += 1;
    }
    if (month % 2 !== 0) {
      month += 1;
      continue; // odd months aren't listed - don't consume a slot
    }
    contracts.push({
      symbol: `GC${GOLD_FUTURES_MONTH_CODE[month]}${String(year).slice(-2)}.CMX`,
      label: `${MONTH_NAME_SHORT[month - 1]} ${year}`,
      month,
      year,
    });
    month += 2;
  }
  return contracts;
}

async function fetchGoldFuturesContract(entry: {
  symbol: string;
  label: string;
  month: number;
  year: number;
}): Promise<GoldFuturesContractQuote> {
  const base: GoldFuturesContractQuote = {
    symbol: entry.symbol,
    label: entry.label,
    month: entry.month,
    year: entry.year,
    price: null,
  };
  try {
    const upstream = await fetch(
      `https://query1.finance.yahoo.com/v8/finance/chart/${encodeURIComponent(entry.symbol)}?interval=1d&range=5d`,
      { headers: { 'User-Agent': YAHOO_UA } }
    );
    if (!upstream.ok) return { ...base, error: `HTTP ${upstream.status}` };
    const json: any = await upstream.json();
    const meta = json?.chart?.result?.[0]?.meta;
    if (!meta || typeof meta.regularMarketPrice !== 'number') {
      return { ...base, error: 'No quote in provider response' };
    }
    return { ...base, price: meta.regularMarketPrice };
  } catch (e: any) {
    return { ...base, error: e?.message || 'Network error' };
  }
}

app.get('/api/market/xau-futures-curve', async (_req, res) => {
  const result = await cachedExternalFeed('xau-futures-curve', 5 * 60_000, async () => {
    const contracts = nextGoldFuturesContracts(5);
    const quotes = await Promise.all(contracts.map(fetchGoldFuturesContract));
    if (quotes.every((q) => q.price === null)) {
      // Same reasoning as the commodities board above: zero of five answering is a provider
      // outage, not five coincidences - throw so the stale snapshot (if any) is served flagged,
      // not a curve of nulls presented as a quiet market.
      throw new Error(quotes[0]?.error || 'No futures contract quotes returned');
    }
    return quotes;
  });

  res.json({
    curve: result.value ?? [],
    source: 'Yahoo Finance (COMEX gold futures, individual contract months)',
    fetchedAt: result.fetchedAt,
    stale: result.stale,
    unavailable: result.value === null,
    error: result.error,
  });
});

// --- Central Bank Gold Buying, Tier 1 (Tahap D3, blueprint §14) ---------------------------------
//
// NOT the WGC XLSX ("Changes_latest_as_of_<Month>_IFS.xlsx") - confirmed HTTP 403 across two
// separate GitHub Actions verification rounds, even with a Referer header simulating a real
// visit from the listing page. Source here is WGC's own free, public, unauthenticated monthly
// "Gold Focus" blog post ("Central bank gold statistics: <Month> <Year>") - same underlying data
// (IMF IFS + central bank reports, cited in the post's own source line), just published as a
// readable article instead of a gated file.
//
// This IS genuinely fragile - confirmed via GitHub Actions (5 audit rounds,
// scripts/audit-wgc-imf-structure.ts, removed after use) that the post has NO <table> and NO
// embedded chart JSON with the actual figures; the country/tonnage list is PROSE, e.g.:
//   "Poland remains the top buyer (82t), followed by Uzbekistan (41t), China (40t)..."
//   "Turkey remains the largest y-t-d seller (83t)..."
//   "Russia also sold gold, with 44t net sales y-t-d"
// A WGC copy change can silently break this. Per the brief's explicit instruction, this degrades
// to `unavailable: true` with a specific reason whenever confidence is low - never a stale count
// presented as current, never a guessed number for a match that didn't parse cleanly.

// Countries WGC's monthly post has actually named as buyers/sellers, historically - not the full
// UN member list, both to keep the match fast and to avoid an unrelated common word coincidentally
// matching a rarely-relevant country name inside unrelated prose (a real risk with short names).
const CENTRAL_BANK_GOLD_COUNTRIES = [
  'China', 'Poland', 'Russia', 'Turkey', 'Türkiye', 'India', 'Kazakhstan', 'Uzbekistan',
  'Czech Republic', 'Qatar', 'Singapore', 'Chile', 'Azerbaijan', 'Iraq', 'Egypt', 'Jordan',
  'Mongolia', 'Philippines', 'Cambodia', 'Ghana', 'Serbia', 'Bulgaria', 'Belarus', 'Ecuador',
  'Colombia', 'Brazil', 'South Korea', 'Thailand', 'Kyrgyzstan', 'Tajikistan', 'Bolivia',
  'Slovakia', 'Hungary', 'Germany', 'Uruguay', 'El Salvador', 'Zambia', 'Kuwait', 'Oman',
  'Morocco', 'Pakistan', 'Sri Lanka', 'Nigeria', 'Vietnam', 'Indonesia', 'Poland',
];
const CENTRAL_BANK_GOLD_COUNTRY_PATTERN = CENTRAL_BANK_GOLD_COUNTRIES
  .map((c) => c.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'))
  .join('|');

/** Sentence-scoped extraction: a sentence containing "sold"/"seller"/"sales"/"selling" flags
 * every country mentioned in it as a net SELLER (negative); everything else defaults to buyer
 * (positive), matching the post's own convention of listing buyers first without a sell keyword.
 * A number is only accepted from within 60 chars AFTER the country name (covers both the
 * "Country (Nt)" and "Country ... with Nt" phrasings actually observed), and only once per
 * country (first mention wins - a later y-t-d recap of the same country is skipped, not double
 * counted). Implausible values (<=0 or >500t in one month) are dropped rather than trusted. */
function extractCentralBankGoldRows(articleText: string): CentralBankGoldRow[] {
  const rows: CentralBankGoldRow[] = [];
  const seen = new Set<string>();
  const sentences = articleText.split(/(?<=[.!?])\s+/);
  const numberRe = /\(?\s*(\d+(?:\.\d+)?)\s*t\b/i;

  for (const sentence of sentences) {
    const sellSignal = /\bsold\b|\bseller\b|\bsales\b|\bselling\b/i.test(sentence);
    const countryRe = new RegExp(`\\b(${CENTRAL_BANK_GOLD_COUNTRY_PATTERN})\\b`, 'gi');
    let m: RegExpExecArray | null;
    while ((m = countryRe.exec(sentence)) !== null) {
      const country = m[1];
      const key = country.toLowerCase();
      if (seen.has(key)) continue;
      const window = sentence.slice(m.index + m[0].length, m.index + m[0].length + 60);
      const numMatch = window.match(numberRe);
      if (!numMatch) continue;
      const tonnes = parseFloat(numMatch[1]);
      if (!Number.isFinite(tonnes) || tonnes <= 0 || tonnes > 500) continue;
      seen.add(key);
      rows.push({ country, changeTonnes: sellSignal ? -tonnes : tonnes });
    }
  }
  return rows;
}

const CENTRAL_BANK_GOLD_UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) HEVORA/1.0';

async function fetchCentralBankGoldTier1(): Promise<{
  rows: CentralBankGoldRow[];
  lastReportedMonth: string;
  postUrl: string;
}> {
  const indexRes = await fetch('https://www.gold.org/goldhub/gold-focus', {
    headers: { 'User-Agent': CENTRAL_BANK_GOLD_UA, Accept: 'text/html' },
  });
  if (!indexRes.ok) throw new Error(`Gold Focus index HTTP ${indexRes.status}`);
  const indexHtml = await indexRes.text();
  const postLinks = [
    ...new Set(
      [...indexHtml.matchAll(/href="(\/goldhub\/gold-focus\/\d{4}\/\d{2}\/[^"]*central-bank[^"]*)"/gi)].map(
        (m) => m[1]
      )
    ),
  ];
  if (postLinks.length === 0) throw new Error('No "central bank" post link found on Gold Focus index page');
  const postUrl = new URL(postLinks[0], 'https://www.gold.org').toString();

  const postRes = await fetch(postUrl, { headers: { 'User-Agent': CENTRAL_BANK_GOLD_UA, Accept: 'text/html' } });
  if (!postRes.ok) throw new Error(`Gold Focus post HTTP ${postRes.status}`);
  const postHtml = await postRes.text();

  const h1Match = postHtml.match(/<h1[^>]*>([\s\S]*?)<\/h1>/i);
  const h1Text = h1Match ? h1Match[1].replace(/<[^>]+>/g, '').trim() : '';
  const monthMatch = h1Text.match(/([A-Za-z]+)\s+(\d{4})\s*$/);
  if (!monthMatch) throw new Error(`Could not parse reporting month from post headline: "${h1Text}"`);
  const lastReportedMonth = `${monthMatch[1]} ${monthMatch[2]}`;

  const articleText = postHtml
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ');
  const rows = extractCentralBankGoldRows(articleText);
  if (rows.length < 3) {
    // Fewer than 3 countries extracted from a post that (per the audited format) normally lists
    // 5-9 - format likely changed. Fail loudly rather than publish a suspiciously thin list.
    throw new Error(`Only ${rows.length} country row(s) extracted - WGC post format may have changed`);
  }

  return { rows, lastReportedMonth, postUrl };
}

app.get('/api/macro/central-bank-gold', async (_req, res) => {
  const result = await cachedExternalFeed('central-bank-gold-tier1', 24 * 60 * 60_000, fetchCentralBankGoldTier1);

  res.json({
    rows: result.value?.rows ?? [],
    lastReportedMonth: result.value?.lastReportedMonth ?? null,
    postUrl: result.value?.postUrl ?? null,
    source: 'World Gold Council - Gold Focus (monthly blog, IMF IFS + central banks)',
    fetchedAt: result.fetchedAt,
    stale: result.stale,
    unavailable: result.value === null,
    error: result.error,
  });
});

// --- ETF Gold Flow: SPDR GLD holdings (PRIORITY 3B, 2026-08-26 data-freshness audit) -----------
//
// GoldIntelligenceHub's own head comment used to say "there is no Delivery & Inventory, Physical
// Market or ETF Flow tab, because this build has no data for those" - live-verified via GitHub
// Actions before this was written that this is no longer true for GLD specifically: SPDR publishes
// a genuine daily historical archive, free, no key, as a real XLSX workbook at the URL below (found
// by scraping the actual download link off SPDR's own historical-data page - a guessed static CSV
// filename returned a PDF instead, so this is the confirmed real link, not an assumption). The
// workbook has TWO sheets - a "Disclaimer" cover sheet and the real "US GLD Historical Archive"
// data table - reading only the first sheet (this app's original probe) silently returns nothing
// but disclaimer text, which is why the sheet is selected by name below, not by default index.
//
// IAU (iShares) has NO equivalent here: two rounds of investigation found no real CSV/XML download
// link on its product page (unlike GLD's, it appears to be rendered client-side, not present in
// the static HTML), so IAU stays honest-unavailable rather than guessed at.
const GLD_HISTORICAL_ARCHIVE_URL = 'https://api.spdrgoldshares.com/api/v1/historical-archive?product=gld&exchange=NYSE&lang=en';
const GLD_DATA_SHEET_NAME = 'US GLD Historical Archive';
// How many trailing trading days to keep - the full archive goes back to 2004 (5000+ rows), far
// more than any reader needs for a "how has GLD's holdings moved lately" card. ~2 years of trading
// days, comfortably more than the 30D read the UI actually uses.
const GLD_MAX_POINTS = 500;

const GLD_MONTH_ABBR: Record<string, number> = {
  jan: 0, feb: 1, mar: 2, apr: 3, may: 4, jun: 5, jul: 6, aug: 7, sep: 8, oct: 9, nov: 10, dec: 11,
};

/** SPDR's own date format is "18-Nov-2004", not machine-parseable via a generic Date() call in
 *  every engine - parsed explicitly against a fixed month-abbreviation table instead of trusting
 *  runtime-dependent heuristic parsing. Returns null for anything that doesn't match (including
 *  "US Holiday" placeholder rows the workbook uses for non-trading days), which the caller drops
 *  rather than padding forward - a holiday has no real tonnage figure, not a repeated one. */
function parseSpdrDate(raw: unknown): string | null {
  if (typeof raw !== 'string') return null;
  const m = /^(\d{1,2})-([A-Za-z]{3})-(\d{4})$/.exec(raw.trim());
  if (!m) return null;
  const month = GLD_MONTH_ABBR[m[2].toLowerCase()];
  if (month === undefined) return null;
  const day = Number(m[1]);
  const year = Number(m[3]);
  const d = new Date(Date.UTC(year, month, day));
  if (isNaN(d.getTime())) return null;
  return d.toISOString().slice(0, 10);
}

const spdrNumberOrNull = (raw: unknown): number | null => (typeof raw === 'number' && Number.isFinite(raw) ? raw : null);

interface GldHoldingsPoint {
  date: string;
  tonnes: number | null;
  closingPriceUsd: number | null;
  totalNetAssetValueUsd: number | null;
}

async function fetchGldHoldings(): Promise<GldHoldingsPoint[]> {
  const upstream = await fetchWithTimeout(GLD_HISTORICAL_ARCHIVE_URL, {
    headers: { 'User-Agent': 'HEVORA/1.0', Accept: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' },
  });
  if (!upstream.ok) throw new Error(`HTTP ${upstream.status}`);
  const buffer = Buffer.from(await upstream.arrayBuffer());

  const sheets = await readExcelFile(buffer);
  const dataSheet = sheets.find((s) => s.sheet === GLD_DATA_SHEET_NAME);
  if (!dataSheet) {
    throw new Error(`Expected sheet "${GLD_DATA_SHEET_NAME}" not found - workbook structure may have changed (sheets: ${sheets.map((s) => s.sheet).join(', ')})`);
  }

  // Row shape (0-indexed, confirmed against a real download):
  // 0 Date | 1 Closing Price | 2 Ounces/Share | 3 NAV/Share | 4 Indicative Price | 5 Mid bid/ask |
  // 6 Premium/Discount | 7 Daily Share Volume | 8 Total Ounces in Trust | 9 Tonnes of Gold |
  // 10 Total Net Asset Value in the Trust
  const points: GldHoldingsPoint[] = [];
  for (const row of dataSheet.data) {
    const date = parseSpdrDate(row[0]);
    if (!date) continue; // header row, "US Holiday" row, or unparseable - skip, never pad
    points.push({
      date,
      tonnes: spdrNumberOrNull(row[9]),
      closingPriceUsd: spdrNumberOrNull(row[1]),
      totalNetAssetValueUsd: spdrNumberOrNull(row[10]),
    });
  }
  if (points.length === 0) throw new Error('Parsed the workbook but found zero usable rows - column layout may have changed');

  points.sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : 0));
  return points.slice(-GLD_MAX_POINTS);
}

app.get('/api/macro/gld-holdings', async (_req, res) => {
  const result = await cachedExternalFeed('gld-holdings', 6 * 60 * 60_000, fetchGldHoldings);

  res.json({
    points: result.value ?? [],
    source: 'SPDR Gold Shares (State Street Global Advisors) - daily historical archive',
    fetchedAt: result.fetchedAt,
    stale: result.stale,
    unavailable: result.value === null,
    error: result.error,
  });
});

// One year of daily closes from Yahoo, shared by the commodity board and the FX pairs. A null
// close is a non-trading session in Yahoo's series; dropping it keeps the series honest, while
// carrying the previous close forward would invent a session that never traded.
async function fetchYahooDailyCloses(
  yahooSymbol: string,
  range: string = '1y'
): Promise<Array<{ date: string; close: number }>> {
  const upstream = await fetch(
    `https://query1.finance.yahoo.com/v8/finance/chart/${encodeURIComponent(yahooSymbol)}?interval=1d&range=${encodeURIComponent(range)}`,
    { headers: { 'User-Agent': YAHOO_UA } }
  );
  if (!upstream.ok) throw new Error(`HTTP ${upstream.status}`);
  const json: any = await upstream.json();
  const block = json?.chart?.result?.[0];
  const stamps: number[] = Array.isArray(block?.timestamp) ? block.timestamp : [];
  const closes: Array<number | null> = block?.indicators?.quote?.[0]?.close ?? [];
  if (stamps.length === 0 || closes.length === 0) throw new Error('No candles in provider response');

  const points = stamps
    .map((ts, i) => ({ date: new Date(ts * 1000).toISOString().slice(0, 10), close: closes[i] }))
    .filter((p): p is { date: string; close: number } => typeof p.close === 'number' && Number.isFinite(p.close));

  if (points.length === 0) throw new Error('Provider returned candles with no usable closes');
  return points;
}

// FX daily closes for the Forex confluence read. Yahoo's spot FX symbols are the pair plus '=X';
// the map is explicit rather than derived so an unknown pair cannot be turned into a URL.
const FX_YAHOO_SYMBOLS: Record<string, string> = {
  EURUSD: 'EURUSD=X',
  GBPUSD: 'GBPUSD=X',
  USDCHF: 'USDCHF=X',
  USDCAD: 'USDCAD=X',
};

app.get('/api/market/fx-history', async (req, res) => {
  const pair = String(req.query.pair || '').toUpperCase();
  const yahooSymbol = FX_YAHOO_SYMBOLS[pair];
  if (!yahooSymbol) {
    res.status(400).json({ pair, points: [], count: 0, error: 'Unknown FX pair', source: 'Yahoo Finance' });
    return;
  }

  const result = await cachedExternalFeed(`fx-history:${pair}`, 6 * 60 * 60_000, () =>
    fetchYahooDailyCloses(yahooSymbol)
  );
  const points = result.value ?? [];
  res.json({
    pair,
    symbol: yahooSymbol,
    points,
    count: points.length,
    source: 'Yahoo Finance (daily closes)',
    fetchedAt: result.fetchedAt,
    stale: result.stale,
    unavailable: result.value === null,
    error: result.error,
  });
});

