async function fetchBitstampRankingRow(cfg: (typeof EXCHANGE_RANKING_INSTRUMENTS)[ExchangeRankingSymbol]): Promise<ExchangeRankingRow | null> {
  try {
    // Bitstamp - SPOT only, no key. No BNB/ADA/DOGE listing history to be confident of either, so
    // those rows are a guess exactly like Kraken/Coinbase's above - a 404 here is simply "not
    // listed", handled by the same !res.ok check as any other failure.
    const res = await fetch(`https://www.bitstamp.net/api/v2/ticker/${cfg.bitstampSymbol}/`, { headers: CRYPTO_FETCH_HEADERS });
    if (!res.ok) return null;
    const json: any = await res.json();
    const price = Number(json?.last);
    // `volume` is 24h volume in the BASE asset - converted to USD via this same ticker's price,
    // same approach as Coinbase's fetcher above.
    const baseVolume = Number(json?.volume);
    if (!Number.isFinite(price)) return null;
    const volume24hUsd = Number.isFinite(baseVolume) ? baseVolume * price : null;
    // `percent_change_24` - Bitstamp's own documented 24h change field, already a percent (e.g.
    // "1.23" = +1.23%), same ticker payload above, no extra call.
    const percentChange24 = Number(json?.percent_change_24);
    const priceChangePercent24h = Number.isFinite(percentChange24) ? percentChange24 : null;

    return {
      exchange: 'Bitstamp',
      price,
      volume24hUsd,
      openInterestUsd: null, // spot exchange - no futures open interest concept
      fundingRatePercent: null, // spot exchange - no funding rate concept
      priceChangePercent24h,
      longShortRatio: null,
    };
  } catch {
    return null;
  }
}

async function fetchGeminiRankingRow(cfg: (typeof EXCHANGE_RANKING_INSTRUMENTS)[ExchangeRankingSymbol]): Promise<ExchangeRankingRow | null> {
  try {
    // Gemini - SPOT only, no key. The v2 ticker is fetched alongside v1 (one extra call, in
    // parallel) purely for its `open` field - v1 (bid/ask/last/volume, used below) has no 24h-
    // open/change field at all, unlike every other fetcher in this file which reuses an already-
    // present field.
    const [res, v2Res] = await Promise.all([
      fetch(`https://api.gemini.com/v1/pubticker/${cfg.geminiSymbol}`, { headers: CRYPTO_FETCH_HEADERS }),
      fetch(`https://api.gemini.com/v2/ticker/${cfg.geminiSymbol}`, { headers: CRYPTO_FETCH_HEADERS }),
    ]);
    if (!res.ok) return null;
    const json: any = await res.json();
    // FIX (audit follow-up, scripts/audit-deribit-gemini.ts): Gemini's `last` field is the most
    // recent TRADE price, which on a thin pair can be a real but stale/outlier print - live-
    // verified on BNB-USD, where `last` read ~4% away from every other exchange while `bid`/`ask`
    // (the actual current order book) agreed with everyone else within cents. Using the bid/ask
    // midpoint instead - the standard "current price" read for a thinly-traded book - falls back
    // to `last` only if bid/ask aren't both present and finite.
    const bid = Number(json?.bid);
    const ask = Number(json?.ask);
    const last = Number(json?.last);
    const price = Number.isFinite(bid) && Number.isFinite(ask) ? (bid + ask) / 2 : Number.isFinite(last) ? last : null;
    if (price === null) return null;
    // Gemini's own `volume` object already carries a USD-denominated total (keyed by the quote
    // currency, 'USD' for every pair used here) - read directly rather than derived, unlike
    // Coinbase/Bitstamp above which only expose base-asset volume.
    const volume24hUsd = Number(json?.volume?.USD);

    let priceChangePercent24h: number | null = null;
    if (v2Res.ok) {
      const v2Json: any = await v2Res.json();
      const open = Number(v2Json?.open);
      if (Number.isFinite(open) && open > 0) priceChangePercent24h = ((price - open) / open) * 100;
    }

    return {
      exchange: 'Gemini',
      price,
      volume24hUsd: Number.isFinite(volume24hUsd) ? volume24hUsd : null,
      openInterestUsd: null,
      fundingRatePercent: null,
      priceChangePercent24h,
      longShortRatio: null,
    };
  } catch {
    return null;
  }
}

async function fetchCryptocomRankingRow(cfg: (typeof EXCHANGE_RANKING_INSTRUMENTS)[ExchangeRankingSymbol]): Promise<ExchangeRankingRow | null> {
  try {
    // Crypto.com Exchange (not the Crypto.com App) - SPOT ticker, no key.
    const res = await fetch(`https://api.crypto.com/exchange/v1/public/get-tickers?instrument_name=${cfg.cryptocomSymbol}`, {
      headers: CRYPTO_FETCH_HEADERS,
    });
    if (!res.ok) return null;
    const json: any = await res.json();
    const row = json?.result?.data?.[0];
    const price = Number(row?.a); // 'a' = last traded price, per Crypto.com Exchange's own field naming
    if (!Number.isFinite(price)) return null;
    // 'vv' = 24h traded volume VALUE (already USD-denominated), per the same field naming - not
    // 'v' (volume in the base asset), which would need a price multiply like Coinbase/Bitstamp.
    const volume24hUsd = Number(row?.vv);
    // 'c' - Crypto.com Exchange's own documented 24h price-change field (fraction, e.g.
    // 0.105 = +10.5%), same ticker payload above, no extra call.
    const c = Number(row?.c);
    const priceChangePercent24h = Number.isFinite(c) ? c * 100 : null;

    return {
      exchange: 'Crypto.com',
      price,
      volume24hUsd: Number.isFinite(volume24hUsd) ? volume24hUsd : null,
      openInterestUsd: null,
      fundingRatePercent: null,
      priceChangePercent24h,
      longShortRatio: null,
    };
  } catch {
    return null;
  }
}

async function fetchDeribitRankingRow(cfg: (typeof EXCHANGE_RANKING_INSTRUMENTS)[ExchangeRankingSymbol]): Promise<ExchangeRankingRow | null> {
  // BTC/ETH use Deribit's USD-settled inverse perpetuals ('{COIN}-PERPETUAL'); SOL/BNB/XRP/ADA/
  // DOGE only exist there USDC-settled ('{COIN}_USDC-PERPETUAL') - confirmed via
  // scripts/audit-deribit-gemini.ts against Deribit's own get_instruments endpoint, not guessed
  // (the original guess, a plain '{COIN}-PERPETUAL' for every coin, was live-verified wrong -
  // Deribit answered only 2/7 pairs). Every symbol has a value now, but the empty-string guard
  // stays as a safe default for any future pair Deribit genuinely doesn't list at all.
  if (!cfg.deribitSymbol) return null;
  try {
    const res = await fetch(`https://www.deribit.com/api/v2/public/ticker?instrument_name=${cfg.deribitSymbol}`, {
      headers: CRYPTO_FETCH_HEADERS,
    });
    if (!res.ok) return null;
    const json: any = await res.json();
    const row = json?.result;
    const price = Number(row?.last_price);
    if (!Number.isFinite(price)) return null;

    // `stats.volume_usd` is Deribit's own documented USD-denominated 24h volume figure.
    const volume24hUsd = Number(row?.stats?.volume_usd);
    // `open_interest` for Deribit's BTC/ETH/SOL perpetuals is already reported in USD by
    // Deribit's own API (the same convention every public aggregator reads it by, unlike
    // OKX/KuCoin above which needed their own coin-to-USD conversion) - not cross-checked against
    // a second source the way this project prefers, so treat with the same caution as Kraken's OI
    // above if this ever looks implausible in a live check.
    const openInterestUsd = Number(row?.open_interest);
    // `funding_8h` - trailing 8h funding rate, dimensionless (e.g. 0.0001), same convention OKX's
    // own per-8h fundingRate already uses elsewhere in this file.
    const fundingRate = Number(row?.funding_8h);
    // `stats.price_change` - Deribit's own documented 24h price-change field, already a percent
    // (e.g. -2.36 = -2.36%), same ticker payload above, no extra call.
    const priceChange = Number(row?.stats?.price_change);
    const priceChangePercent24h = Number.isFinite(priceChange) ? priceChange : null;

    return {
      exchange: 'Deribit',
      price,
      volume24hUsd: Number.isFinite(volume24hUsd) ? volume24hUsd : null,
      openInterestUsd: Number.isFinite(openInterestUsd) ? openInterestUsd : null,
      fundingRatePercent: Number.isFinite(fundingRate) ? fundingRate * 100 : null,
      priceChangePercent24h,
      // No public long/short account-ratio equivalent to OKX/Bybit's.
      longShortRatio: null,
    };
  } catch {
    return null;
  }
}

async function fetchBitmexRankingRow(cfg: (typeof EXCHANGE_RANKING_INSTRUMENTS)[ExchangeRankingSymbol]): Promise<ExchangeRankingRow | null> {
  // FIX (audit follow-up, scripts/audit-deribit-gemini.ts): the original '{COIN}USDT' guess was
  // wrong across the board - 'BTCUSDT' doesn't exist on BitMEX at all, and the real 'XBTUSDT'/
  // '{COIN}_USDT' linear listings that DO exist returned prices 6-21% off every other exchange
  // with $0 or implausible turnover, i.e. thinly/never-traded listings, not genuinely live
  // markets. Fixed to use BitMEX's real liquid market instead - 'XBTUSD'/'ETHUSD', the classic
  // USD-quoted inverse perpetuals (confirmed via /api/v1/instrument/active: real non-zero
  // turnover, quoteCurrency literally 'USD' so no conversion ambiguity). BNB/ADA/DOGE aren't
  // listed on BitMEX at all; SOL/XRP have no real, live BitMEX market at all right now - `if
  // (!cfg.bitmexSymbol)` below skips all 5 rather than shipping another wrong/dead-market row.
  if (!cfg.bitmexSymbol) return null;
  try {
    const res = await fetch(`https://www.bitmex.com/api/v1/instrument?symbol=${cfg.bitmexSymbol}`, { headers: CRYPTO_FETCH_HEADERS });
    if (!res.ok) return null;
    const rows: any[] = await res.json();
    const row = Array.isArray(rows) ? rows[0] : null;
    const price = Number(row?.lastPrice);
    if (!Number.isFinite(price)) return null;

    // `turnover24h` on XBTUSD/ETHUSD is denominated in `quoteCurrency`, which the audit confirmed
    // is literally 'USD' for these two instruments - a direct, unambiguous USD figure, unlike the
    // USDT-linear contracts' turnover24h above (which didn't reconcile cleanly with contract
    // multiplier and was dropped for that reason).
    const volume24hUsd = Number(row?.turnover24h);
    // `fundingRate` is BitMEX's own documented dimensionless rate (not an absolute payment like
    // Kraken's field of the same name turned out to be) - taken directly, same as OKX/Bitget/MEXC.
    const fundingRate = Number(row?.fundingRate);
    // `lastChangePcnt` - BitMEX's own documented 24h price-change ratio (fraction, e.g.
    // 0.0123 = +1.23%), same instrument payload above, no extra call.
    const lastChangePcnt = Number(row?.lastChangePcnt);
    const priceChangePercent24h = Number.isFinite(lastChangePcnt) ? lastChangePcnt * 100 : null;
    // Open interest left null: XBTUSD/ETHUSD are INVERSE contracts (negative `multiplier`), whose
    // OI-to-USD conversion is a different, not-yet-verified formula from the coin-margined linear
    // contracts (OKX/KuCoin) this file already converts elsewhere - not guessed.
    return {
      exchange: 'BitMEX',
      price,
      volume24hUsd: Number.isFinite(volume24hUsd) ? volume24hUsd : null,
      openInterestUsd: null,
      fundingRatePercent: Number.isFinite(fundingRate) ? fundingRate * 100 : null,
      priceChangePercent24h,
      longShortRatio: null,
    };
  } catch {
    return null;
  }
}

async function fetchDydxRankingRow(cfg: (typeof EXCHANGE_RANKING_INSTRUMENTS)[ExchangeRankingSymbol]): Promise<ExchangeRankingRow | null> {
  if (!cfg.dydxTicker) return null;
  try {
    const res = await fetch(`https://indexer.dydx.trade/v4/perpetualMarkets?ticker=${cfg.dydxTicker}`, { headers: CRYPTO_FETCH_HEADERS });
    if (!res.ok) return null;
    const json: any = await res.json();
    const row = json?.markets?.[cfg.dydxTicker];
    if (!row) return null; // dYdX genuinely doesn't list this market - not an error
    const price = Number(row?.oraclePrice);
    if (!Number.isFinite(price)) return null;

    // dYdX v4 is a USD-settled perpetual DEX - `volume24H` is already a real USD figure, no
    // conversion needed.
    const volume24hUsd = Number(row?.volume24H);
    // `openInterest` is in the BASE asset (number of BTC/ETH/... contracts), converted to USD via
    // this same market's own oracle price - a real conversion, not a guess (same pattern OKX's
    // fetcher above uses for its own coin-denominated OI field).
    const openInterestBase = Number(row?.openInterest);
    const openInterestUsd = Number.isFinite(openInterestBase) ? openInterestBase * price : null;
    // `nextFundingRate` on dYdX v4 is a PER-HOUR rate (dYdX settles funding continuously/hourly,
    // not every 8h like OKX/Bitget/MEXC above) - reported as-is per this file's own documented
    // convention (ExchangeRankingRow.fundingRatePercent: "per the exchange's own funding
    // settlement interval... never presented as a normalized-to-8h number").
    const fundingRate = Number(row?.nextFundingRate);
    // `priceChange24H` - dYdX v4's own documented 24h price change, but as an ABSOLUTE quote-
    // currency delta (dollars), not a percent - the 24h-ago price is derived from it and this same
    // market's current oraclePrice (both already fetched above, no extra call) to get a real %.
    const priceChange24H = Number(row?.priceChange24H);
    let priceChangePercent24h: number | null = null;
    if (Number.isFinite(priceChange24H)) {
      const open24h = price - priceChange24H;
      if (open24h > 0) priceChangePercent24h = (priceChange24H / open24h) * 100;
    }

    return {
      exchange: 'dYdX',
      price,
      volume24hUsd: Number.isFinite(volume24hUsd) ? volume24hUsd : null,
      openInterestUsd,
      fundingRatePercent: Number.isFinite(fundingRate) ? fundingRate * 100 : null,
      priceChangePercent24h,
      longShortRatio: null,
    };
  } catch {
    return null;
  }
}

async function fetchHyperliquidRankingRow(cfg: (typeof EXCHANGE_RANKING_INSTRUMENTS)[ExchangeRankingSymbol]): Promise<ExchangeRankingRow | null> {
  if (!cfg.hyperliquidCoin) return null;
  try {
    // Hyperliquid's public info endpoint - POST, no key. One request returns EVERY listed asset's
    // context (same "fetch the whole tickers list, pick out one row" shape as Kraken's fetcher
    // above); meta.universe[i] and assetCtxs[i] are parallel arrays, matched here by coin name
    // rather than assumed index (listing order isn't documented as stable).
    const res = await fetch('https://api.hyperliquid.xyz/info', {
      method: 'POST',
      headers: { ...CRYPTO_FETCH_HEADERS, 'Content-Type': 'application/json' },
      body: JSON.stringify({ type: 'metaAndAssetCtxs' }),
    });
    if (!res.ok) return null;
    const json: any = await res.json();
    const universe: any[] = json?.[0]?.universe ?? [];
    const assetCtxs: any[] = json?.[1] ?? [];
    const idx = universe.findIndex((u) => u?.name === cfg.hyperliquidCoin);
    if (idx < 0) return null; // genuinely not listed - not an error
    const ctx = assetCtxs[idx];
    const price = Number(ctx?.markPx);
    if (!Number.isFinite(price)) return null;

    // `dayNtlVlm` is Hyperliquid's own documented USD-notional 24h volume - no conversion needed
    // (Hyperliquid perpetuals are USD-quoted).
    const volume24hUsd = Number(ctx?.dayNtlVlm);
    // `openInterest` is in the BASE asset - converted to USD via this same asset's own markPx,
    // same real-conversion pattern as OKX/dYdX above.
    const openInterestBase = Number(ctx?.openInterest);
    const openInterestUsd = Number.isFinite(openInterestBase) ? openInterestBase * price : null;
    // `funding` is Hyperliquid's own PER-HOUR rate (Hyperliquid settles funding hourly, not every
    // 8h) - reported as-is, same "don't fake a normalized window" rule as dYdX's rate above.
    const fundingRate = Number(ctx?.funding);
    // `prevDayPx` - Hyperliquid's own documented price 24h ago, same asset context above, no
    // extra call.
    const prevDayPx = Number(ctx?.prevDayPx);
    const priceChangePercent24h = Number.isFinite(prevDayPx) && prevDayPx > 0 ? ((price - prevDayPx) / prevDayPx) * 100 : null;

    return {
      exchange: 'Hyperliquid',
      price,
      volume24hUsd: Number.isFinite(volume24hUsd) ? volume24hUsd : null,
      openInterestUsd,
      fundingRatePercent: Number.isFinite(fundingRate) ? fundingRate * 100 : null,
      priceChangePercent24h,
      longShortRatio: null,
    };
  } catch {
    return null;
  }
}

