// ==========================================
// ADMIN AUTHENTICATION (HTTP BASIC AUTH + RATE LIMITER)
// ==========================================

const ADMIN_LOGIN_ATTEMPT_WINDOW_MS = 15 * 60 * 1000;
const loginAttempts = new Map<string, { count: number; firstAttempt: number }>();

// Bounds loginAttempts's memory growth - same fix as apiRateLimitState/askAiRateLimitState above,
// but a real security gap on top of the memory concern: requireAdminAuth below only ever deletes
// an IP's entry lazily, when that SAME IP visits again after its window expires (or succeeds).
// getClientIp() trusts the client-supplied X-Forwarded-For header with no upstream-proxy
// validation, so an attacker (or just a botnet-style scanner hitting /api/admin/*, a common
// automated target) can trivially send a fresh fake IP on every request - each one fails once,
// never revisits, and would otherwise sit in this map forever. This sweep drops any entry whose
// window has expired regardless of whether that IP ever comes back.
setInterval(() => {
  const now = Date.now();
  for (const [ip, attempt] of loginAttempts) {
    if (now - attempt.firstAttempt >= ADMIN_LOGIN_ATTEMPT_WINDOW_MS) loginAttempts.delete(ip);
  }
}, 10 * 60_000);

function getClientIp(req: express.Request): string {
  const xForwardedFor = req.headers['x-forwarded-for'];
  if (xForwardedFor) {
    const rawIp = Array.isArray(xForwardedFor) ? xForwardedFor[0] : xForwardedFor;
    const clientIp = rawIp.split(',')[0].trim();
    if (clientIp) return clientIp;
  }
  return req.ip || req.socket?.remoteAddress || 'unknown';
}

function verifyAdminCredentials(userIn: string, passIn: string): boolean {
  const inputUser = (userIn || '').trim();
  const inputPass = (passIn || '').trim();

  const expectedUser = (process.env.ADMIN_USERNAME || 'hevora_admin_821c0a').trim();
  if (inputUser !== expectedUser) return false;

  const plainPassEnv = (process.env.ADMIN_PASSWORD || '').trim();
  if (plainPassEnv) {
    return inputPass === plainPassEnv;
  }

  const expectedPassHash = (process.env.ADMIN_PASSWORD_HASH || '8443a015f3dcf4547e05aff4f42b2e93401472b77adfbdea514dbb5ad6d9c9ca').trim();
  const hashedInput = crypto.createHash('sha256').update(inputPass).digest('hex');
  return hashedInput === expectedPassHash || inputPass === expectedPassHash;
}

function requireAdminAuth(req: express.Request, res: express.Response, next: express.NextFunction) {
  const ip = getClientIp(req);
  const now = Date.now();
  const attempt = loginAttempts.get(ip);

  if (attempt) {
    if (now - attempt.firstAttempt >= ADMIN_LOGIN_ATTEMPT_WINDOW_MS) {
      loginAttempts.delete(ip);
    } else if (attempt.count >= 5) {
      console.log(`[ADMIN AUTH RATE LIMITED] IP: ${ip}, waktu: ${new Date().toISOString()}`);
      return res.status(429).json({ error: 'Terlalu banyak percobaan login gagal. Coba lagi dalam beberapa menit.' });
    }
  }

  let authenticated = false;
  const authHeader = req.headers.authorization;
  if (authHeader && authHeader.toLowerCase().startsWith('basic ')) {
    const base64Part = authHeader.substring(6).trim();
    try {
      const decoded = Buffer.from(base64Part, 'base64').toString('utf8');
      const colonIndex = decoded.indexOf(':');
      if (colonIndex !== -1) {
        const username = decoded.substring(0, colonIndex);
        const password = decoded.substring(colonIndex + 1);
        if (verifyAdminCredentials(username, password)) {
          authenticated = true;
        }
      }
    } catch (e) {
      // ignore parse error
    }
  }

  if (authenticated) {
    loginAttempts.delete(ip);
    console.log(`[ADMIN AUTH SUCCESS] IP: ${ip}, waktu: ${new Date().toISOString()}`);
    return next();
  }

  // Failed attempt update
  const currentAttempt = loginAttempts.get(ip);
  if (!currentAttempt) {
    loginAttempts.set(ip, { count: 1, firstAttempt: now });
  } else {
    currentAttempt.count += 1;
  }

  console.log(`[ADMIN AUTH FAILED] IP: ${ip}, waktu: ${new Date().toISOString()}`);
  res.setHeader('WWW-Authenticate', 'Basic realm="HEVORA Admin"');
  return res.status(401).json({ error: 'Akses khusus admin required (Unauthorized).' });
}

// Admin Auth Routes
