app.post('/api/admin/reset-history', requireAdminAuth, async (_req, res) => {
  try {
    completedHistoryRecords = [];

    // Overwrite HISTORY_FILE with empty array
    try {
      fs.writeFileSync(HISTORY_FILE, JSON.stringify([], null, 2));
    } catch (e) {
      console.error('[ADMIN RESET HISTORY] Failed writing history_store.json:', e);
    }

    // Delete all monthly archive files in ARCHIVE_DIR
    if (fs.existsSync(ARCHIVE_DIR)) {
      const files = fs.readdirSync(ARCHIVE_DIR).filter((f) => f.startsWith('history_archive_') && f.endsWith('.json'));
      for (const file of files) {
        try {
          fs.unlinkSync(path.join(ARCHIVE_DIR, file));
        } catch (e) {
          console.error(`[ADMIN RESET HISTORY] Failed deleting ${file}:`, e);
        }
      }
    }

    // Overwrite Redis key 'hevora:history'
    await safeRedisCall(
      () => redisClient!.set('hevora:history', []),
      'resetHistory'
    );

    // Also clear the safety-net list (HISTORY_RECENT_LIST_KEY) - otherwise loadStoredHistory()'s
    // recovery-merge would "resurrect" the just-deleted records from it on the next load.
    await safeRedisCall(
      () => redisClient!.del(HISTORY_RECENT_LIST_KEY),
      'resetHistory_clearSafetyNet'
    );

    res.json({ success: true, message: 'History telah direset total.' });
  } catch (err) {
    console.error('Admin reset-history error:', err);
    res.status(500).json({ success: false, error: 'Gagal mereset history' });
  }
});

// 2026-09-01 (URGENT, real-production bug fix): a fire-and-forget race in
// archiveForexClosedBarsIfNew/archiveCryptoClosedBarsIfNew (see their own comments above - fixed
// in this same commit with a per-pair in-flight guard) had already corrupted the EUR/USD, GBP/USD,
// USD/CHF, USD/CAD archives with duplicate/out-of-order entries before the fix landed (confirmed
// via check-forex-archive-status.ts against real production data - median inter-bar gap of 0s).
// This admin action clears ONE known archive key (never an arbitrary Redis key - pairId/interval
// are validated against the same fixed pair lists/suffixes every archive route already uses) and
// resets this process's own in-memory trackers for that pair, so the NEXT successful fetch cycle
// re-initializes cleanly and the archive rebuilds from empty with the race now fixed. A reusable
// maintenance tool, not a one-off script, in case a future archive ever needs the same recovery.
const CLEARABLE_ARCHIVE_INTERVALS: Record<string, readonly string[]> = {
  XAUUSD: ['5m'],
  BTCUSDT: ['5m'], ETHUSDT: ['5m'], SOLUSDT: ['5m'],
  EURUSD: ['1m'], GBPUSD: ['1m'], USDCHF: ['1m'], USDCAD: ['1m'],
};
app.post('/api/admin/clear-candle-archive', requireAdminAuth, async (req, res) => {
  try {
    const pairId = String(req.body?.pairId || req.query.pairId || '').toUpperCase();
    const interval = String(req.body?.interval || req.query.interval || '');
    const validIntervals = CLEARABLE_ARCHIVE_INTERVALS[pairId];
    if (!validIntervals || !validIntervals.includes(interval)) {
      res.status(400).json({
        success: false,
        error: `Unknown pairId/interval combination. Valid pairs: ${Object.keys(CLEARABLE_ARCHIVE_INTERVALS).join(', ')} (each with its own fixed interval).`,
      });
      return;
    }
    const archiveKey = `hevora:candlearchive:${pairId}:${interval}`;
    const delResult = await safeRedisCall(() => redisClient!.del(archiveKey), `admin_clear_archive_${pairId.toLowerCase()}`);
    if (delResult === null) {
      res.status(503).json({ success: false, error: 'Redis unavailable - could not clear the archive key. Try again shortly.' });
      return;
    }

    // Reset this process's own in-memory trackers so the next fetch cycle re-initializes from the
    // now-empty archive instead of comparing against a stale lastPushedTimeMs from before the clear.
    if (pairId === 'XAUUSD') {
      xauArchiveLastPushedTimeMs = null;
    } else if ((CRYPTO_ARCHIVE_PAIRS as readonly string[]).includes(pairId)) {
      const p = pairId as typeof CRYPTO_ARCHIVE_PAIRS[number];
      delete cryptoArchiveLastPushedTimeMs[p];
      cryptoArchiveInitialized[p] = false;
    } else if ((FOREX_ARCHIVE_PAIRS as readonly string[]).includes(pairId)) {
      const p = pairId as typeof FOREX_ARCHIVE_PAIRS[number];
      delete forexArchiveLastPushedTimeMs[p];
      forexArchiveInitialized[p] = false;
    }

    res.json({ success: true, message: `Cleared ${archiveKey}. It will rebuild from empty on the next successful fetch cycle for ${pairId}.` });
  } catch (err) {
    console.error('Admin clear-candle-archive error:', err);
    res.status(500).json({ success: false, error: 'Gagal menghapus arsip candle' });
  }
});

