async function loadStoredEngineSettings(): Promise<EngineSettings> {
  try {
    const redisRes = await safeRedisGetWithRetry<EngineSettings>('hevora:engine_settings', 'load_engine_settings');
    if (redisRes && typeof redisRes === 'object' && redisRes !== null) {
      return { autoBreakevenEnabled: Boolean(redisRes.autoBreakevenEnabled) };
    }
  } catch (e) {}

  if (fs.existsSync(ENGINE_SETTINGS_FILE)) {
    try {
      const data = JSON.parse(fs.readFileSync(ENGINE_SETTINGS_FILE, 'utf8'));
      if (data && typeof data === 'object') {
        return { autoBreakevenEnabled: Boolean(data.autoBreakevenEnabled) };
      }
    } catch (e) {}
  }
  return { autoBreakevenEnabled: false };
}

