// ==========================================
// RISK ACKNOWLEDGMENT (per-user, versioned consent for the Market tab)
// ==========================================
//
// This is NOT the passive DisclaimerModal the site already shows. That one is informational and
// dismissible; this is a recorded consent tied to a specific Clerk user, capturing which statements
// they ticked, the name they signed with, and when. It gates the Market tab's signals.
//
// Storage: one Redis key per user, `hevora:risk_ack:<clerkUserId>`, matching the layout the task
// asked for (a per-user key rather than one big blob keeps a write from ever clobbering another
// user's record under concurrency). The local-file fallback mirrors the same data as a single JSON
// map, exactly like every other store here does when Redis isn't configured.
//
// Versioning: an acknowledgment is only "current" while its disclaimerVersion equals
// DISCLAIMER_VERSION (src/types.ts). Bump that constant when the wording changes and every existing
// user is asked to sign again - deliberately, because a signature against old text is not consent
// to new text.

function riskAckRedisKey(userId: string): string {
  return `hevora:risk_ack:${userId}`;
}

/** Reads the whole local-file fallback map. Only used when Redis is unavailable. */
function loadRiskAckFileMap(): Record<string, RiskAcknowledgment> {
  if (!fs.existsSync(RISK_ACK_FILE)) return {};
  try {
    const data = JSON.parse(fs.readFileSync(RISK_ACK_FILE, 'utf8'));
    return data && typeof data === 'object' ? data : {};
  } catch (e) {
    return {};
  }
}

async function loadRiskAcknowledgment(userId: string): Promise<RiskAcknowledgment | null> {
  try {
    const redisRes = await safeRedisGetWithRetry<RiskAcknowledgment>(riskAckRedisKey(userId), 'load_risk_ack');
    if (redisRes && typeof redisRes === 'object' && typeof redisRes.disclaimerVersion === 'string') {
      return redisRes;
    }
  } catch (e) {
    // Fall through to the file fallback below.
  }
  const map = loadRiskAckFileMap();
  return map[userId] || null;
}

async function saveRiskAcknowledgment(ack: RiskAcknowledgment): Promise<void> {
  // Local file first so the record survives even if Redis is down at this instant - consent is the
  // kind of thing that must not be silently lost.
  try {
    const map = loadRiskAckFileMap();
    map[ack.userId] = ack;
    fs.writeFileSync(RISK_ACK_FILE, JSON.stringify(map, null, 2), 'utf8');
  } catch (e) {
    // Silent - the Redis write below is the primary path in production.
  }
  const res = await safeRedisCall(() => redisClient!.set(riskAckRedisKey(ack.userId), ack), 'save_risk_ack');
  if (res === null) {
    console.error(
      `[DATA AT RISK] Risk acknowledgment for ${ack.userId} is only on local disk, NOT in Redis. It will be lost on restart and the user will be asked to sign again.`
    );
  }
}

/** Resolves the Clerk user id from the request's Bearer token, or answers 401 and returns null.
 * The id ALWAYS comes from the verified token, never from the request body - otherwise a client
 * could record consent under someone else's account. */
async function requireClerkUser(req: express.Request, res: express.Response): Promise<string | null> {
  const authHeader = req.headers.authorization || '';
  const token = authHeader.startsWith('Bearer ') ? authHeader.slice(7) : '';
  if (!token || !process.env.CLERK_SECRET_KEY) {
    res.status(401).json({ success: false, error: 'Unauthorized' });
    return null;
  }
  try {
    const payload = await verifyToken(token, { secretKey: process.env.CLERK_SECRET_KEY });
    return payload.sub;
  } catch (err) {
    res.status(401).json({ success: false, error: 'Invalid or expired session' });
    return null;
  }
}

app.get('/api/user/risk-acknowledgment', async (req, res) => {
  const userId = await requireClerkUser(req, res);
  if (!userId) return;

  try {
    const ack = await loadRiskAcknowledgment(userId);
    // needsAcknowledgment is computed here rather than in the browser so the version comparison
    // lives in exactly one place and the client can't be out of step with the server's idea of
    // what the current text is.
    const payload: RiskAcknowledgmentStatus = {
      success: true,
      needsAcknowledgment: !ack || ack.disclaimerVersion !== DISCLAIMER_VERSION,
      currentVersion: DISCLAIMER_VERSION,
      acknowledgedVersion: ack ? ack.disclaimerVersion : null,
      acknowledgedAt: ack ? ack.acknowledgedAt : null,
    };
    res.json(payload);
  } catch (err) {
    console.error('[RISK ACK GET ERROR]', err);
    res.status(500).json({ success: false, error: 'Gagal membaca status pernyataan risiko.' });
  }
});

app.post('/api/user/risk-acknowledgment', async (req, res) => {
  const userId = await requireClerkUser(req, res);
  if (!userId) return;

  const { checkedItems, signatureName } = req.body || {};

  // Every required statement must be present. Validated server-side and not merely disabled in the
  // UI: a disabled button is a convenience, not a control - the record is only worth something if
  // the server refuses to write an incomplete one.
  const provided: string[] = Array.isArray(checkedItems) ? checkedItems.filter((i: unknown) => typeof i === 'string') : [];
  const missing = RISK_CONSENT_ITEM_IDS.filter((id) => !provided.includes(id));
  if (missing.length > 0) {
    return res.status(400).json({
      success: false,
      error: 'Semua pernyataan risiko wajib dicentang.',
      detail: `Belum dicentang: ${missing.join(', ')}`,
    });
  }

  const trimmedName = typeof signatureName === 'string' ? signatureName.trim() : '';
  if (!trimmedName) {
    return res.status(400).json({ success: false, error: 'Nama lengkap sebagai tanda tangan digital wajib diisi.' });
  }

  try {
    const ack: RiskAcknowledgment = {
      userId,
      disclaimerVersion: DISCLAIMER_VERSION,
      // Stored in the canonical order defined by RISK_CONSENT_ITEM_IDS rather than whatever order
      // the client happened to send, so records stay comparable over time.
      checkedItems: RISK_CONSENT_ITEM_IDS.filter((id) => provided.includes(id)),
      signatureName: trimmedName.slice(0, 120),
      acknowledgedAt: new Date().toISOString(),
    };
    await saveRiskAcknowledgment(ack);
    console.log(`[RISK ACK] Recorded for ${userId} (version ${DISCLAIMER_VERSION}).`);

    const payload: RiskAcknowledgmentStatus = {
      success: true,
      needsAcknowledgment: false,
      currentVersion: DISCLAIMER_VERSION,
      acknowledgedVersion: ack.disclaimerVersion,
      acknowledgedAt: ack.acknowledgedAt,
    };
    res.json(payload);
  } catch (err) {
    console.error('[RISK ACK POST ERROR]', err);
    res.status(500).json({ success: false, error: 'Gagal menyimpan pernyataan risiko.' });
  }
});
