// Reaction tracker: forward-collects atPublish (captured immediately on publish above) then
// after15m/after1h as real time passes - same pattern as captureMarketReactionSnapshots() for
// Economic History, reusing captureCurrentMarketSnapshot() verbatim.
let liveEventReactionCaptureInFlight = false;

async function captureLiveEventReactionSnapshots(): Promise<void> {
  if (liveEventReactionCaptureInFlight) return;
  liveEventReactionCaptureInFlight = true;
  try {
    const events = await loadStoredLiveEvents();
    const now = Date.now();
    let changed = false;

    // Only ever needs to look at recent events - anything older than ~2h has already had its
    // after1h captured (or never will, if the server was down at the time - left as null rather
    // than guessed).
    const cutoffMs = now - 2 * 60 * 60 * 1000;
    for (const evt of events) {
      const createdMs = new Date(evt.createdAt).getTime();
      if (isNaN(createdMs) || createdMs < cutoffMs) continue;

      if (!evt.reaction.after15m && now - createdMs >= 15 * 60 * 1000) {
        evt.reaction.after15m = captureCurrentMarketSnapshot();
        changed = true;
      }
      if (!evt.reaction.after1h && now - createdMs >= 60 * 60 * 1000) {
        evt.reaction.after1h = captureCurrentMarketSnapshot();
        changed = true;
      }
    }

    if (changed) {
      await saveStoredLiveEvents(events);
      console.log('[LIVE EVENT REACTION] Captured new snapshot(s) for tracked live event(s).');
    }
  } catch (err) {
    console.error('[LIVE EVENT REACTION CAPTURE ERROR]', err);
  } finally {
    liveEventReactionCaptureInFlight = false;
  }
}

